-- Copa do Mundo 2026 — seed idempotente
-- Placeholder schedule: 12 groups (A-L) x 4 teams = 48 placeholders.
-- Calendário aproximado (UTC). Datas/horários devem ser confirmados quando o calendário oficial da FIFA estiver completo.
-- 104 partidas: 72 fase de grupos + 16 oitavas (R32) + 8 R16 + 4 quartas + 2 semis + 1 disputa 3o + 1 final.

ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, group_name=EXCLUDED.group_name, flag_emoji=EXCLUDED.flag_emoji;

WITH t AS (SELECT code, id FROM public.teams)
ON CONFLICT (external_match_id) DO UPDATE SET home_team_id=EXCLUDED.home_team_id, away_team_id=EXCLUDED.away_team_id, kickoff_at=EXCLUDED.kickoff_at, stage=EXCLUDED.stage, group_name=EXCLUDED.group_name, is_knockout=EXCLUDED.is_knockout, is_mock=EXCLUDED.is_mock, status=EXCLUDED.status;
